        if not section.exists() or not section.is_dir():
            continue
        for item in section.rglob("*.md"):
            try:
                rel = item.relative_to(section)
                if item.is_file() and not any(part.startswith(".") for part in rel.parts):
                    pages.append(item)
            except Exception:
